sed -i '/val ACTIVE_TRIGGER/a\        val FINGERPRINT_ENABLED = booleanPreferencesKey("fingerprint_enabled")\n        val POWER_BUTTON_ENABLED = booleanPreferencesKey("power_button_enabled")\n        val BACK_PANEL_ENABLED = booleanPreferencesKey("back_panel_enabled")' app/src/main/java/com/example/SettingsRepository.kt

sed -i '/val activeTrigger: Flow<TriggerMethod>/i\    val fingerprintEnabled: Flow<Boolean> = context.dataStore.data.map { it[FINGERPRINT_ENABLED] ?: true }\n    val powerButtonEnabled: Flow<Boolean> = context.dataStore.data.map { it[POWER_BUTTON_ENABLED] ?: false }\n    val backPanelEnabled: Flow<Boolean> = context.dataStore.data.map { it[BACK_PANEL_ENABLED] ?: false }\n' app/src/main/java/com/example/SettingsRepository.kt

sed -i '/suspend fun setActiveTrigger/i\    suspend fun setFingerprintEnabled(enabled: Boolean) { context.dataStore.edit { it[FINGERPRINT_ENABLED] = enabled } }\n    suspend fun setPowerButtonEnabled(enabled: Boolean) { context.dataStore.edit { it[POWER_BUTTON_ENABLED] = enabled } }\n    suspend fun setBackPanelEnabled(enabled: Boolean) { context.dataStore.edit { it[BACK_PANEL_ENABLED] = enabled } }\n' app/src/main/java/com/example/SettingsRepository.kt
